<?php
declare(strict_types=1); require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/layout.php'; requireAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf($_POST['csrf_token']??null);$leaseId=filter_input(INPUT_POST,'lease_id',FILTER_VALIDATE_INT);$month=trim((string)($_POST['month_year']??''));$utility=(float)($_POST['utility_amount']??0);$stmt=$pdo->prepare("SELECT * FROM leases WHERE id=:id AND status='active'");$stmt->execute([':id'=>$leaseId]);$lease=$stmt->fetch();if(!$lease||!preg_match('/^\\d{4}-\\d{2}$/',$month)||$utility<0)redirectWith('invoices.php','error','Enter valid invoice details.');$stmt=$pdo->prepare('INSERT INTO invoices (lease_id,tenant_id,month_year,rent_amount,utility_amount,total_amount,due_date) VALUES (:lease_id,:tenant_id,:month,:rent,:utility,:total,:due)');$stmt->execute([':lease_id'=>$leaseId,':tenant_id'=>$lease['tenant_id'],':month'=>$month,':rent'=>$lease['monthly_rent'],':utility'=>$utility,':total'=>(float)$lease['monthly_rent']+$utility,':due'=>$month.'-28']);redirectWith('invoices.php','success','Invoice generated.');}
$leases=$pdo->query("SELECT l.id,l.monthly_rent,u.full_name,r.room_number FROM leases l JOIN users u ON u.id=l.tenant_id JOIN rooms r ON r.id=l.room_id WHERE l.status='active' ORDER BY u.full_name")->fetchAll();$invoices=$pdo->query('SELECT i.*,u.full_name FROM invoices i JOIN users u ON u.id=i.tenant_id ORDER BY i.due_date DESC')->fetchAll();pageHeader('Invoices');?><div class="grid gap-6 lg:grid-cols-3"><section class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm"><h1 class="text-xl font-bold">Generate invoice</h1><form class="mt-4 space-y-3" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><select class="w-full rounded border p-2" name="lease_id" required><?php foreach($leases as $lease):?><option value="<?=e((string)$lease['id'])?>"><?=e($lease['full_name'].' · '.$lease['room_number'])?></option><?php endforeach;?></select><input class="w-full rounded border p-2" type="month" name="month_year" required><input class="w-full rounded border p-2" type="number" step="0.01" min="0" name="utility_amount" placeholder="Utility amount" required><button class="rounded bg-teal-700 px-4 py-2 font-semibold text-white">Generate</button></form></section><section class="rounded-lg border border-slate-200 bg-white p-6 shadow-sm lg:col-span-2"><h2 class="text-xl font-bold">Invoice register</h2><div class="mt-4 space-y-2"><?php foreach($invoices as $invoice):?><div class="flex justify-between border-b pb-2"><span><?=e($invoice['full_name'].' · '.$invoice['month_year'])?></span><span><?=money($invoice['total_amount'])?> <?=badge($invoice['status'])?></span></div><?php endforeach;?></div></section></div><?php pageFooter();?>